/**
 * Vorlagen fuer Texte, in die React zur Laufzeit Werte einsetzt —
 * Meldungen wie „12 Titel hinzugefügt.“, die nie wortgleich im
 * Quelltext stehen. `{1}`, `{2}` … stehen fuer die eingesetzten
 * Teile; daraus werden ankervolle Regexen mit Fanggruppen gebaut.
 * Einträge mit Einzahl/Mehrzahl-Ternären im Quelltext stehen hier
 * doppelt — einmal je Laufzeitform.
 */
